<!DOCTYPE html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?></head><body class="mis-admin-page"><div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?><main class="content-area" id="mainContent"><div class="app-page-head d-flex flex-wrap justify-content-between gap-2"><div><h1 class="h4">System Monitoring</h1><p class="small text-muted">Measured application and database checks. Refresh on demand; no continuous polling.</p></div><button class="btn btn-outline-primary" id="refreshMonitoring">Refresh health checks</button></div><p id="monitoringStatus" role="status"></p><div class="row g-3"><div class="col-lg-6"><section class="card p-3 h-100"><h2 class="h6">Application and database</h2><dl><dt>Database connectivity</dt><dd id="healthDatabase"><?=$data['database_connected']?'Connected':'Unavailable'?></dd><dt>Monitoring API</dt><dd id="healthApi">Not yet probed in this browser</dd><dt>Application error telemetry</dt><dd><?=e($data['application_error_telemetry'])?></dd><dt>Server CPU, memory and uptime</dt><dd>Unavailable; no trusted host telemetry source is configured.</dd></dl></section></div><div class="col-lg-6"><section class="card p-3 h-100"><h2 class="h6">Continuity and background work</h2><dl><dt>Latest backup</dt><dd id="healthBackup"><?=e($data['last_backup']['status']??'Not recorded')?></dd><dt>Departure worker last successful run</dt><dd id="healthWorker"><?=e($data['departure_worker_last_run']??'Not reported')?></dd><dt>Scheduled administrator departures</dt><dd id="healthScheduled"><?=(int)$data['scheduled_departures']?></dd><dt>Due departures awaiting worker</dt><dd id="healthOverdue"><?=(int)$data['overdue_departures']?></dd></dl><p class="small text-muted">Schedule setup/run_admin_departures.php with the server task scheduler. Access deadlines are also enforced at authentication even if the worker is delayed. The application cannot certify that a host scheduler is installed.</p><a href="backups.php" class="btn btn-outline-secondary">Backup &amp; Recovery</a></section></div></div></main></div></div><?php include __DIR__.'/../../components/footer.php'; ?><script>
(function(){const button=document.getElementById('refreshMonitoring'),status=document.getElementById('monitoringStatus');button.addEventListener('click',async function(){button.disabled=true;status.textContent='Checking?';const start=performance.now();try{const response=await fetch(APP_URL+'/api/admin_dashboard.php',{credentials:'same-origin',signal:AbortSignal.timeout(15000)}),result=await response.json();if(!response.ok||!result.success)throw Error('System checks are unavailable.');const d=result.data;document.getElementById('healthDatabase').textContent=d.database_connected?'Connected':'Unavailable';document.getElementById('healthApi').textContent='Responded in '+Math.round(performance.now()-start)+' ms (browser round trip)';document.getElementById('healthBackup').textContent=d.last_backup?.status||'Not recorded';document.getElementById('healthScheduled').textContent=d.scheduled_departures;document.getElementById('healthWorker').textContent=d.departure_worker_last_run||'Not reported';document.getElementById('healthOverdue').textContent=d.overdue_departures;status.textContent='Checks completed at '+d.generated_at;}catch(error){status.textContent='Unable to refresh. Last available values are shown.';}finally{button.disabled=false;}});})();
